package game.map;

import game.map.cells.Cell;
import game.map.cells.FillableCell;
import game.map.cells.TerminationCell;
import game.map.cells.Wall;
import game.pipes.Pipe;
import io.Deserializer;
import util.Coordinate;
import util.Direction;
import util.StringUtils;

import java.util.*;

public class Map {

    private final int rows;
    private final int cols;
    public final Cell[][] cells;

    private TerminationCell sourceCell;
    private TerminationCell sinkCell;

    private final Set<Coordinate> filledTiles = new HashSet<>();
    private int prevFilledTiles = 0;
    private Integer prevFilledDistance;

    public Map(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new Cell[rows][cols];
        // Initialize all cells to null or Wall, as appropriate
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                this.cells[i][j] = null;
            }
        }
    }

    public Map(int rows, int cols, Cell[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new Cell[rows][cols];
        int sourceCount = 0;
        int sinkCount = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                this.cells[i][j] = cells[i][j];
                if (cells[i][j] instanceof TerminationCell) {
                    TerminationCell t = (TerminationCell) cells[i][j];
                    if (t.type == TerminationCell.Type.SOURCE) {
                        sourceCount++;
                        sourceCell = t;
                    } else if (t.type == TerminationCell.Type.SINK) {
                        sinkCount++;
                        sinkCell = t;
                    }
                }
            }
        }
        if (sourceCount != 1 || sinkCount != 1) {
            throw new IllegalArgumentException("Map must have exactly one source and one sink.");
        }
        // Additional checks for source/sink placement can be added here if needed
    }

    static Map fromString(int rows, int cols, String cellsRep) {
        Cell[][] cells = Deserializer.parseString(rows, cols, cellsRep);
        return new Map(rows, cols, cells);
    }

    public boolean tryPlacePipe(final Coordinate coord, final Pipe pipe) {
        return tryPlacePipe(coord.row, coord.col, pipe);
    }

    boolean tryPlacePipe(int row, int col, Pipe p) {
        // Convert to 0-based index
        int i = row;
        int j = col;
        if (i < 0 || i >= rows || j < 0 || j >= cols) return false;
        Cell cell = cells[i][j];
        if (cell instanceof FillableCell) {
            FillableCell fillable = (FillableCell) cell;
            if (fillable.getPipe().isPresent()) {
                return false; // already occupied
            }
            fillable.setPipe(p);
            return true;
        }
        return false;
    }

    public void display() {
        final int padLength = Integer.valueOf(rows - 1).toString().length();

        Runnable printColumns = () -> {
            System.out.print(StringUtils.createPadding(padLength, ' '));
            System.out.print(' ');
            for (int i = 0; i < cols - 2; ++i) {
                System.out.print((char) ('A' + i));
            }
            System.out.println();
        };

        printColumns.run();

        for (int i = 0; i < rows; ++i) {
            if (i != 0 && i != rows - 1) {
                System.out.print(String.format("%1$" + padLength + "s", i));
            } else {
                System.out.print(StringUtils.createPadding(padLength, ' '));
            }

            Arrays.stream(cells[i]).forEachOrdered(elem -> System.out.print(elem.toSingleChar()));

            if (i != 0 && i != rows - 1) {
                System.out.print(i);
            }

            System.out.println();
        }

        printColumns.run();
    }

    public void undo(final Coordinate coord) {
        int i = coord.row;
        int j = coord.col;
        if (i < 0 || i >= rows || j < 0 || j >= cols) {
            throw new IllegalArgumentException("Coordinate out of bounds");
        }
        Cell cell = cells[i][j];
        if (!(cell instanceof FillableCell)) {
            throw new IllegalArgumentException("Cell is not fillable");
        }
        FillableCell fillable = (FillableCell) cell;
        fillable.setPipe(null);
    }

    public void fillBeginTile() {
        sourceCell.setFilled();
        filledTiles.clear();
        filledTiles.add(sourceCell.coord);
    }

    public void fillTiles(int distance) {
        // BFS from sourceCell up to 'distance'
        Queue<Coordinate> queue = new LinkedList<>();
        Set<Coordinate> visited = new HashSet<>();
        Map<Coordinate, Integer> distMap = new HashMap<>();

        queue.add(sourceCell.coord);
        visited.add(sourceCell.coord);
        distMap.put(sourceCell.coord, 0);

        filledTiles.clear();
        sourceCell.setFilled();
        filledTiles.add(sourceCell.coord);

        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();
            int currDist = distMap.get(curr);

            if (currDist >= distance) continue;

            Cell cell = cells[curr.row][curr.col];
            List<Direction> directions = new ArrayList<>();

            if (cell instanceof TerminationCell) {
                TerminationCell tcell = (TerminationCell) cell;
                directions.add(tcell.pointingTo);
            } else if (cell instanceof FillableCell) {
                FillableCell fcell = (FillableCell) cell;
                if (fcell.getPipe().isPresent()) {
                    Pipe pipe = fcell.getPipe().get();
                    directions.addAll(Arrays.asList(pipe.getConnections()));
                    pipe.setFilled();
                }
            }

            for (Direction dir : directions) {
                Coordinate next = new Coordinate(curr.row + dir.getOffset().row, curr.col + dir.getOffset().col);
                if (next.row < 0 || next.row >= rows || next.col < 0 || next.col >= cols) continue;
                if (visited.contains(next)) continue;
                Cell nextCell = cells[next.row][next.col];

                // Check if the connection is valid
                if (nextCell instanceof FillableCell) {
                    FillableCell nextFillable = (FillableCell) nextCell;
                    if (nextFillable.getPipe().isPresent()) {
                        Pipe nextPipe = nextFillable.getPipe().get();
                        // Check if the pipe connects back to current cell
                        for (Direction nextDir : nextPipe.getConnections()) {
                            Coordinate back = new Coordinate(next.row + nextDir.getOffset().row, next.col + nextDir.getOffset().col);
                            if (back.equals(curr)) {
                                nextPipe.setFilled();
                                queue.add(next);
                                visited.add(next);
                                distMap.put(next, currDist + 1);
                                filledTiles.add(next);
                                break;
                            }
                        }
                    }
                } else if (nextCell instanceof TerminationCell) {
                    TerminationCell nextTerm = (TerminationCell) nextCell;
                    // Only allow if the direction matches
                    if (nextTerm.pointingTo == dir.getOpposite()) {
                        nextTerm.setFilled();
                        queue.add(next);
                        visited.add(next);
                        distMap.put(next, currDist + 1);
                        filledTiles.add(next);
                    }
                }
            }
        }
        prevFilledTiles = filledTiles.size();
        prevFilledDistance = distance;
    }

    public boolean checkPath() {
        // BFS from sourceCell to sinkCell
        Queue<Coordinate> queue = new LinkedList<>();
