        // BFS from source to sink
        Queue<CoordDir> queue = new LinkedList<>();
        Set<Coordinate> visited = new HashSet<>();
        queue.add(new CoordDir(sourceCell.coord, sourceCell.pointingTo));
        visited.add(sourceCell.coord);

        while (!queue.isEmpty()) {
            CoordDir current = queue.poll();
            Coordinate coord = current.coord;
            Direction dir = current.dir;

            Coordinate next = coord.add(dir.getOffset());
            if (next.row < 0 || next.row >= rows || next.col < 0 || next.col >= cols)
                continue;
            if (visited.contains(next))
                continue;
            Cell nextCell = cells[next.row][next.col];
            if (nextCell instanceof FillableCell) {
                FillableCell fillable = (FillableCell) nextCell;
                if (fillable.getPipe().isPresent()) {
                    Pipe pipe = fillable.getPipe().get();
                    for (Direction pipeDir : pipe.getConnections()) {
                        if (pipeDir == dir.getOpposite()) {
                            // Continue along other connections
                            for (Direction outDir : pipe.getConnections()) {
                                if (outDir != dir.getOpposite()) {
                                    queue.add(new CoordDir(next, outDir));
                                }
                            }
                            visited.add(next);
                            break;
                        }
                    }
                }
            } else if (nextCell instanceof TerminationCell) {
                TerminationCell tc = (TerminationCell) nextCell;
                if (tc.type == TerminationCell.Type.SINK && tc.pointingTo == dir.getOpposite()) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * <p>
     * Hint: The game is lost when a round ends and no pipes are filled during the round. Is
     * there a way to check whether pipes are filled during a round?
     * </p>
     *
     * @return {@code true} if the game is lost.
     */
    public boolean hasLost() {
        // If no new tiles were filled in the last fillTiles call
        return prevFilledTiles == 0;
    }

    // Helper classes for BFS
    private static class CoordDist {
        Coordinate coord;
        int dist;
        Direction fromDir;

        CoordDist(Coordinate coord, int dist, Direction fromDir) {
            this.coord = coord;
            this.dist = dist;
            this.fromDir = fromDir;
        }
    }

    private static class CoordDir {
        Coordinate coord;
        Direction dir;

        CoordDir(Coordinate coord, Direction dir) {
            this.coord = coord;
            this.dir = dir;
        }
    }
}
