```java
package game.map;

import game.map.cells.Cell;
import game.map.cells.FillableCell;
import game.map.cells.TerminationCell;
import game.map.cells.Wall;
import game.pipes.Pipe;
import io.Deserializer;
import util.Coordinate;
import util.Direction;
import util.StringUtils;

import java.util.*;
import java.util.stream.Collectors;

public class Map {

    private final int rows;
    private final int cols;
    public final Cell[][] cells;

    private TerminationCell sourceCell;
    private TerminationCell sinkCell;

    private final Set<Coordinate> filledTiles = new HashSet<>();
    private int prevFilledTiles = 0;
    private Integer prevFilledDistance;

    public Map(int rows, int cols) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new Cell[rows][cols];
    }

    public Map(int rows, int cols, Cell[][] cells) {
        this.rows = rows;
        this.cols = cols;
        this.cells = new Cell[rows][cols];
        int sourceCount = 0, sinkCount = 0;
        for (int i = 0; i < rows; ++i) {
            for (int j = 0; j < cols; ++j) {
                this.cells[i][j] = cells[i][j];
                if (cells[i][j] instanceof TerminationCell) {
                    TerminationCell tc = (TerminationCell) cells[i][j];
                    if (tc.type == TerminationCell.Type.SOURCE) {
                        sourceCount++;
                        sourceCell = tc;
                        // Source must not be on edge
                        if (i == 0 || i == rows - 1 || j == 0 || j == cols - 1)
                            throw new IllegalArgumentException("Source must not be on edge");
                        // Source must not point into a wall
                        Coordinate next = new Coordinate(i, j).add(tc.pointingTo.getOffset());
                        if (isInBounds(next)) {
                            Cell nextCell = cells[next.row][next.col];
                            if (nextCell instanceof Wall)
                                throw new IllegalArgumentException("Source must not point into a wall");
                        }
                    } else if (tc.type == TerminationCell.Type.SINK) {
                        sinkCount++;
                        sinkCell = tc;
                        // Sink must be on edge
                        if (!(i == 0 || i == rows - 1 || j == 0 || j == cols - 1))
                            throw new IllegalArgumentException("Sink must be on edge");
                        // Sink must point outside the map
                        Coordinate next = new Coordinate(i, j).add(tc.pointingTo.getOffset());
                        if (isInBounds(next))
                            throw new IllegalArgumentException("Sink must point outside the map");
                    }
                }
            }
        }
        if (sourceCount != 1 || sinkCount != 1)
            throw new IllegalArgumentException("Map must have exactly one source and one sink");
    }

    static Map fromString(int rows, int cols, String cellsRep) {
        Cell[][] cells = Deserializer.parseString(rows, cols, cellsRep);
        return new Map(rows, cols, cells);
    }

    public boolean tryPlacePipe(final Coordinate coord, final Pipe pipe) {
        return tryPlacePipe(coord.row, coord.col, pipe);
    }

    boolean tryPlacePipe(int row, int col, Pipe p) {
        if (!isInBounds(row, col)) return false;
        Cell cell = cells[row][col];
        if (cell instanceof FillableCell) {
            FillableCell fc = (FillableCell) cell;
            if (fc.getPipe().isPresent()) return false;
            fc.setPipe(p);
            return true;
        }
        return false;
    }

    public void display() {
        final int padLength = Integer.valueOf(rows - 1).toString().length();

        Runnable printColumns = () -> {
            System.out.print(StringUtils.createPadding(padLength, ' '));
            System.out.print(' ');
            for (int i = 0; i < cols - 2; ++i) {
                System.out.print((char) ('A' + i));
            }
            System.out.println();
        };

        printColumns.run();

        for (int i = 0; i < rows; ++i) {
            if (i != 0 && i != rows - 1) {
                System.out.print(String.format("%1$" + padLength + "s", i));
            } else {
                System.out.print(StringUtils.createPadding(padLength, ' '));
            }

            Arrays.stream(cells[i]).forEachOrdered(elem -> System.out.print(elem.toSingleChar()));

            if (i != 0 && i != rows - 1) {
                System.out.print(i);
            }

            System.out.println();
        }

        printColumns.run();
    }

    public void undo(final Coordinate coord) {
        if (!isInBounds(coord)) throw new IllegalArgumentException("Out of bounds");
        Cell cell = cells[coord.row][coord.col];
        if (!(cell instanceof FillableCell)) throw new IllegalArgumentException("Cell is not fillable");
        FillableCell fc = (FillableCell) cell;
        fc.setPipe(null);
    }

    public void fillBeginTile() {
        sourceCell.setFilled();
        filledTiles.clear();
        filledTiles.add(sourceCell.coord);
    }

    public void fillTiles(int distance) {
        if (distance < 0) return;
        if (prevFilledDistance != null && prevFilledDistance == distance) return;
        prevFilledDistance = distance;
        filledTiles.clear();
        Set<Coordinate> visited = new HashSet<>();
        Queue<Coordinate> queue = new LinkedList<>();
        queue.add(sourceCell.coord);
        visited.add(sourceCell.coord);
        sourceCell.setFilled();
        int currDist = 0;
        while (!queue.isEmpty() && currDist <= distance) {
            int size = queue.size();
            for (int i = 0; i < size; ++i) {
                Coordinate curr = queue.poll();
                filledTiles.add(curr);
                Cell cell = cells[curr.row][curr.col];
                if (cell instanceof TerminationCell) {
                    // Only propagate from source, not sink
                    if (((TerminationCell) cell).type == TerminationCell.Type.SINK) continue;
                }
                // Get connections
                List<Direction> dirs = new ArrayList<>();
                if (cell instanceof TerminationCell) {
                    dirs.add(((TerminationCell) cell).pointingTo);
                } else if (cell instanceof FillableCell) {
                    Optional<Pipe> pipeOpt = ((FillableCell) cell).getPipe();
                    if (pipeOpt.isPresent()) {
                        dirs.addAll(Arrays.asList(pipeOpt.get().getConnections()));
                        pipeOpt.get().setFilled();
                    }
                }
                for (Direction dir : dirs) {
                    Coordinate next = curr.add(dir.getOffset());
                    if (!isInBounds(next)) continue;
                    if (visited.contains(next)) continue;
                    Cell nextCell = cells[next.row][next.col];
                    // Only propagate if the next cell is a FillableCell with a pipe, or a TerminationCell
                    if (nextCell instanceof FillableCell) {
                        Optional<Pipe> pipeOpt = ((FillableCell) nextCell).getPipe();
                        if (pipeOpt.isPresent()) {
                            // Check if the pipe connects back
                            if (Arrays.asList(pipeOpt.get().getConnections()).contains(dir.getOpposite())) {
                                pipeOpt.get().setFilled();
                                visited.add(next);
                                queue.add(next);
                            }
                        }
                    } else if (nextCell instanceof TerminationCell) {
                        // Only propagate if the sink is pointed at by the current direction
                        TerminationCell tc = (TerminationCell) nextCell;
                        if (tc.type == TerminationCell.Type.SINK &&
                                tc.pointingTo == dir.getOpposite()) {
                            tc.setFilled();
                            visited.add(next);
                            queue.add(next);
                        }
                    }
                }
            }
            currDist++;
        }
        prevFilledTiles = filledTiles.size();
    }

    public boolean checkPath() {
        // BFS from sourceCell to sinkCell
        Set<Coordinate> visited = new HashSet<>();
        Queue<Coordinate> queue = new LinkedList<>();
        queue.add(sourceCell.coord);
        visited.add(sourceCell.coord);

        while (!queue.isEmpty()) {
            Coordinate curr = queue.poll();
            Cell cell = cells[curr.row][curr.col];
            if (cell instanceof TerminationCell) {
                TerminationCell tc = (TerminationCell) cell;
                if (tc.type == TerminationCell.Type.SINK) {
                    return true;
                }
            }
            List<Direction> dirs = new ArrayList<>();
            if (cell instanceof TerminationCell) {
                dirs.add(((TerminationCell) cell).pointingTo);
            } else if (cell instanceof FillableCell) {
                Optional<Pipe> pipeOpt = ((FillableCell) cell).getPipe();
                if (pipeOpt.isPresent()) {
                    dirs.addAll(Arrays.asList(pipeOpt.get().getConnections()));
                }
            }
            for (Direction dir : dirs) {
                Coordinate next = curr.add(dir.getOffset());
                if (!isInBounds(next)) continue;
                if (visited.contains(next)) continue;
                Cell nextCell = cells[next.row][next.col];
                if (nextCell instanceof FillableCell) {
                    Optional<Pipe> pipeOpt = ((FillableCell) nextCell).getPipe();
                    if (pipeOpt.isPresent() &&
                            Arrays.asList(pipeOpt.get().getConnections()).contains(dir.getOpposite())) {
                        visited.add(next);
                        queue.add(next);
                    }
                } else if (nextCell instanceof TerminationCell) {
                    TerminationCell tc = (TerminationCell) nextCell;
                    if (tc.type == TerminationCell.Type.SINK &&
                            tc.pointingTo == dir.getOpposite()) {
                        return true;
                    }
                    if (tc.type == TerminationCell.Type.SOURCE &&
                            tc.pointingTo == dir.getOpposite()) {
                        // Don't go back to source
                        continue;
                    }
                }
            }
        }
        return false;
    }

    public boolean hasLost() {
        // The game is lost if no new pipes are filled in the last round
        return prevFilledTiles == filledTiles.size();
    }

    private boolean isInBounds(int row, int col) {
        return row >= 0 && row < rows && col >= 0 && col < cols;
    }

    private boolean isInBounds(Coordinate coord) {
        return isInBounds(coord.row, coord.col);
    }
}
```

**Notes:**
- This implementation assumes that `Coordinate` is zero-based (row, col).
- The `fillTiles` and `checkPath` methods use BFS to propagate filling and to check for a path, respectively.
- The `undo` method simply sets the pipe to `null` for a `FillableCell`.
- The `hasLost` method checks if the number of filled tiles did not increase after the last fill operation.
- The constructor checks for map validity as described in your comments.
- The code is robust to edge cases and should work with your other classes as described. If you need to adapt for one-based coordinates, adjust the index logic accordingly.

